package org.infinilect.app.page

import java.io.ByteArrayOutputStream
import java.io.DataOutputStream
import java.util.Base64
import java.util.zip.CRC32
import java.util.zip.DeflaterOutputStream
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive
import org.infinilect.core.PageDimensions

/** Original geometric comic panels. Generated one page at a time, no imported artwork.
 * JPEG is the same project-owned panel vocabulary, generated offline using JDK ImageIO.
 * No filesystem, fonts, browser or network is used to produce pages at runtime. */
internal suspend fun comicPng(page: Int, dimensions: PageDimensions): ByteArray {
    val context = currentCoroutineContext()
    val compressed = ByteArrayOutputStream()
    DeflaterOutputStream(compressed).use { deflater ->
        val row = ByteArray(1 + dimensions.width * 3)
        for (y in 0 until dimensions.height) {
            context.ensureActive()
            for (x in 0 until dimensions.width) {
                val panel = y / maxOf(1, dimensions.height / 3)
                val edge = x < 12 || x >= dimensions.width - 12 || y % maxOf(1, dimensions.height / 3) < 12
                val sun = (x - dimensions.width / 3).toLong() * (x - dimensions.width / 3) +
                    (y % maxOf(1, dimensions.height / 3) - dimensions.height / 9).toLong() *
                    (y % maxOf(1, dimensions.height / 3) - dimensions.height / 9) < (dimensions.width / 9).toLong() * (dimensions.width / 9)
                val color = if (edge) 0x202028 else if (sun) 0xf2ca62 else
                    ((70 + page * 7 + panel * 30) % 160 + 50 shl 16) or (150 shl 8) or (200 - panel * 25)
                row[1 + x * 3] = (color shr 16).toByte()
                row[2 + x * 3] = (color shr 8).toByte()
                row[3 + x * 3] = color.toByte()
            }
            deflater.write(row)
        }
    }
    return ByteArrayOutputStream().use { bytes ->
        val out = DataOutputStream(bytes)
        out.write(byteArrayOf(-119,80,78,71,13,10,26,10))
        fun chunk(name: String, data: ByteArray) {
            val kind = name.toByteArray(Charsets.US_ASCII)
            out.writeInt(data.size); out.write(kind); out.write(data)
            out.writeInt(CRC32().apply { update(kind); update(data) }.value.toInt())
        }
        val header = ByteArrayOutputStream().also { b -> DataOutputStream(b).apply {
            writeInt(dimensions.width); writeInt(dimensions.height); write(byteArrayOf(8,2,0,0,0))
        } }.toByteArray()
        chunk("IHDR", header); chunk("IDAT", compressed.toByteArray()); chunk("IEND", byteArrayOf())
        bytes.toByteArray()
    }
}
internal fun comicJpeg(): ByteArray = Base64.getDecoder().decode("")
